%% Change watch on documents (spec 068, T-068-04, D5): keeps the check installed exactly where an active rule needs it.
%%
%% The check is a statement trigger generated by the database itself from the catalog (automation.install_watch):
%% with no rule it does not exist, and the table pays nothing. A rule changed (NOTIFY "ana_wake/watch") makes the leader
%% compare what is needed with what is installed (automation.watch_plan) and fix the difference:
%%   - needed and missing or outdated: install or replace the function (replacing never locks the table);
%%   - installed and no longer needed: the function stops comparing at once (cheap) and the trigger is dropped only
%%     after ?LINGER_MS, so turning a rule off and on again does not install and drop over and over.
%% Creating or dropping a trigger waits at most 100 ms for the table (lock_timeout in the function): when a long
%% transaction holds it, the attempt fails, nobody is held up, and the table is tried again with a growing pause.
%% Reading the plan writes nothing; an idle system with rules does not write (spec 063).
-module(ana_watch).
-behaviour(gen_server).

-export([start_link/0, status/0]).
-export([init/1, handle_call/3, handle_cast/2, handle_info/2]).
-export([backoff_ms/1]).

-define(TICK_MS, 30000).
-define(LINGER_MS, 600000).
-define(MAX_BACKOFF_MS, 60000).

start_link() -> gen_server:start_link({local, ?MODULE}, ?MODULE, [], []).

%% What the screens show: tables waiting for a lock, and when they will be tried again.
-spec status() -> map().
status() -> gen_server:call(?MODULE, status).

init([]) ->
    ok = ana_events:subscribe(<<"watch">>),
    erlang:send_after(3000, self(), tick),
    %% unneeded: table => when it stopped being needed; retry: table => {attempts, not before (ms), last error}.
    {ok, #{unneeded => #{}, retry => #{}, timer => undefined}}.

handle_call(status, _From, S = #{retry := R}) ->
    {reply, #{waiting => [#{table => T, attempts => N, error => E} || {T, {N, _, E}} <- maps:to_list(R)]}, S};
handle_call(_, _From, S) -> {reply, {error, unknown}, S}.

handle_cast(_, S) -> {noreply, S}.

handle_info({ana_event, <<"watch">>, _}, S) -> {noreply, reconcile(S)};
handle_info(tick, S) ->
    erlang:send_after(?TICK_MS, self(), tick),
    {noreply, reconcile(S)};
handle_info(retry, S) -> {noreply, reconcile(S#{timer := undefined})};
handle_info(_, S) -> {noreply, S}.

%% Pause before attempt N+1 after N failures: 1 s, 2 s, 4 s… up to a minute.
-spec backoff_ms(pos_integer()) -> pos_integer().
backoff_ms(N) -> min(?MAX_BACKOFF_MS, 1000 bsl min(N - 1, 16)).

reconcile(S) ->
    case leader() of
        false -> S#{unneeded := #{}, retry := #{}};
        true ->
            case ana_db:rows("SELECT * FROM automation.watch_plan()", []) of
                {ok, Plan} -> schedule(lists:foldl(fun step/2, S, Plan));
                {error, E} -> logger:warning("watch: plan not read: ~0p", [E]), S
            end
    end.

step(#{<<"table_name">> := T, <<"needed">> := true, <<"installed">> := I, <<"current">> := C}, S = #{unneeded := U}) ->
    S2 = S#{unneeded := maps:remove(T, U)},
    case I andalso C of
        true -> forget(T, S2);
        false -> install(T, false, S2)
    end;
step(#{<<"table_name">> := T, <<"needed">> := false, <<"current">> := C}, S = #{unneeded := U}) ->
    Now = erlang:monotonic_time(millisecond),
    Since = maps:get(T, U, Now),
    S2 = S#{unneeded := U#{T => Since}},
    case Now - Since >= ?LINGER_MS of
        true ->
            S3 = #{retry := R} = install(T, true, S2),
            case maps:is_key(T, R) of
                true -> S3;                                     % keeps the date: dropped as soon as the lock allows
                false -> S3#{unneeded := maps:remove(T, maps:get(unneeded, S3))}
            end;
        false when not C -> install(T, false, S2);              % stop comparing now; drop later
        false -> S2
    end.

install(T, Drop, S = #{retry := R}) ->
    Now = erlang:monotonic_time(millisecond),
    case maps:get(T, R, undefined) of
        {_, NotBefore, _} when NotBefore > Now -> S;
        Prev ->
            case ana_db:one("SELECT automation.install_watch($1, $2) AS r", [T, Drop]) of
                {ok, #{<<"r">> := What}} ->
                    _ = What =/= <<"unchanged">> andalso
                        ok =:= logger:notice("watch: ~ts ~ts", [T, What]),
                    forget(T, S);
                {error, E} ->
                    N = case Prev of {P, _, _} -> P + 1; undefined -> 1 end,
                    logger:warning("watch: ~ts not ~ts (attempt ~b): ~0p",
                                   [T, case Drop of true -> "dropped"; false -> "installed" end, N, E]),
                    S#{retry := R#{T => {N, Now + backoff_ms(N), reason(E)}}}
            end
    end.

forget(T, S = #{retry := R}) -> S#{retry := maps:remove(T, R)}.

reason(#{message := M}) when is_binary(M) -> M;
reason(E) -> iolist_to_binary(io_lib:format("~0p", [E])).

%% A pending retry wakes the process exactly when it is due.
schedule(S = #{retry := R, timer := undefined}) when map_size(R) > 0 ->
    Now = erlang:monotonic_time(millisecond),
    Next = lists:min([NB || {_, NB, _} <- maps:values(R)]),
    S#{timer := erlang:send_after(max(0, Next - Now), self(), retry)};
schedule(S) -> S.

leader() ->
    case catch ana_scheduler:status() of
        #{leader := true} -> true;
        _ -> false
    end.
